(function(root){
'use strict';
const BASE=Object.freeze({D:9000,vi:97000,vl:103000,sale:148000,ads:24000000,q20:1900,q40:4200,units:25,positions:75,localCapacity:20000,rMode:'components',rDirect:22,capital:12,insurance:2,damage:5,handling:3,f20:6930000,c20:2200000,t20:3000000,a20:700000,f40:8400000,c40:2500000,t40:4000000,a40:700000,tl:368000,il:158000,al:105000,rentPositions:90,expandPositions:90,rent:17000000,expand:13000000,mold:45000000,p:20});
const positive=['D','vi','vl','q20','q40','units'];
function validate(s){const errors=[];for(const k of Object.keys(BASE)){if(k==='rMode')continue;if(typeof s[k]!=='number'||!Number.isFinite(s[k]))errors.push(k+': ingrese un número válido');else if(s[k]<0||positive.includes(k)&&s[k]===0)errors.push(k+': valor fuera de rango');}if(s.p>100)errors.push('p: máximo 100%');if(s.tl+s.il+s.al===0)errors.push('Ordenar local: A = 0 no tiene EOQ positivo alcanzable; revise al menos un componente');if(!['components','direct'].includes(s.rMode))errors.push('Modo de tasa inválido');if(!(rate(s)>0))errors.push('r: debe ser positiva');for(const k of ['positions','rentPositions','expandPositions','units','q20','q40'])if(!Number.isInteger(s[k]))errors.push(k+': debe ser entero');return errors;}
function rate(s){return (s.rMode==='direct'?s.rDirect:s.capital+s.insurance+s.damage+s.handling)/100;}
function capacity(s,Q){const needed=Math.ceil(Q/s.units);return [{name:'Actual',positions:s.positions,cost:0},{name:'Alquiler',positions:s.positions+s.rentPositions,cost:s.rent},{name:'Ampliación',positions:s.positions+s.expandPositions,cost:s.expand}].map(x=>({...x,needed,feasible:needed<=x.positions}));}
function calculate(s){const errors=validate(s);if(errors.length)return {errors};const r=rate(s);const specs=[['20','20 pies',s.f20+s.c20+s.t20+s.a20,s.vi,s.q20],['40','40 pies',s.f40+s.c40+s.t40+s.a40,s.vi,s.q40],['local','Local',s.tl+s.il+s.al,s.vl,null]];
const rows=specs.map(([id,name,A,v,lot])=>{const eoq=Math.sqrt(2*A*s.D/(v*r));const Q=lot===null?eoq:lot;const zero=Q===0;const ordering=zero?0:A*s.D/Q,holding=v*r*Q/2,trc=ordering+holding,minTRC=Math.sqrt(2*A*s.D*v*r);const configs=capacity(s,Q);const supply=id!=='local'||s.D<=s.localCapacity;const viable=configs.filter(x=>x.feasible).sort((a,b)=>a.cost-b.cost);const chosen=viable[0]||null;const mold=id==='local'?s.mold*(1-s.p/100):0;const acquisition=v*s.D;const feasible=!!chosen&&supply;return {id,name,A,v,eoq,Q,ordering,holding,trc,minTRC,mold,acquisition,configs,chosen,supply,feasible,positions:Math.ceil(Q/s.units),orders:zero?Infinity:s.D/Q,cycle:365*Q/s.D,average:Q/2,total:acquisition+trc+(chosen?chosen.cost:0)+mold,delta:Q-eoq,deltaPct:eoq?(Q/eoq-1)*100:null,penalty:trc-minTRC,penaltyPct:minTRC?(trc/minTRC-1)*100:null};});
const ranked=rows.filter(x=>x.feasible).sort((a,b)=>a.total-b.total);const winners=ranked.filter(x=>Math.abs(x.total-ranked[0].total)<0.01);return {errors:[],r,rows,ranked,winners};}
function equilibria(s){const m=calculate(s);if(m.errors.length)return {error:'Datos inválidos'};const imp=m.rows.filter(x=>x.id!=='local'&&x.feasible).sort((a,b)=>a.total-b.total)[0];if(!imp)return {error:'No hay importación factible como referencia.'};const local=m.rows[2];let finance=null;let financeMessage='';if(!local.feasible)financeMessage='Proveedor local no factible: no existe un umbral viable con el precio activo.';else if(s.mold===0)financeMessage=local.total<=imp.total?'Sin costo de molde: financiación mínima 0%.':'Sin costo de molde: la financiación no cambia la decisión.';else{const raw=100*(1-(imp.total-local.acquisition-local.trc-local.chosen.cost)/s.mold);finance=Math.max(0,raw);financeMessage=raw>100?'Financiar todo el molde no basta.':'Financiación mínima viable.';}
let price=null,priceMessage='';if(s.D>s.localCapacity)priceMessage='La demanda supera la capacidad anual local.';else{const maxPositions=Math.max(s.positions,s.positions+s.rentPositions,s.positions+s.expandPositions);if(maxPositions<=0&&local.A>0)priceMessage='No hay capacidad de bodega local.';else{const minPrice=local.A===0?1e-9:2*local.A*s.D/(m.r*(maxPositions*s.units)**2);const cost=v=>{const l=calculate({...s,vl:v}).rows[2];return l.feasible?l.total:Infinity;};if(cost(minPrice*(1+1e-12))>imp.total)priceMessage='Ningún precio físicamente factible resulta competitivo.';else{let lo=Math.max(1e-9,minPrice*(1+1e-12)),hi=Math.max(s.vl,lo*2);while(cost(hi)<=imp.total&&hi<1e15)hi*=2;for(let i=0;i<100;i++){const mid=(lo+hi)/2;if(cost(mid)<=imp.total)lo=mid;else hi=mid;}price=lo;priceMessage='Umbral con EOQ y bodega recalculados.';}}}
return {importation:imp,finance,financeMessage,price,priceMessage,priceResult:price?calculate({...s,vl:price}).rows[2]:null};}
function variation(n){const s={...BASE};if(n===1)s.vl=99000;if(n===2)s.f20=10000000;if(n===3)s.p=50;return s;}
function saw(Q,D,units){if(Q<=0)return [];const T=365*Q/D;const points=[[0,Q/units]];for(let t=T;t<=365;t+=T){points.push([t,0],[t,Q/units]);if(points.length>20000)return points;}points.push([365,(Q-D/365*(365%T))/units]);return points;}
root.EOQ={BASE,validate,rate,capacity,calculate,equilibria,variation,saw};
})(typeof globalThis!=='undefined'?globalThis:this);
